/* voice capture */
.vc{padding:16px}
.vc-top{display:flex;justify-content:space-between}
.vc-wave{display:flex;align-items:center;justify-content:center;gap:3px;height:64px;margin:12px 0}
.vc-wave i{width:4px;height:4px;background:rgba(var(--fg-rgb),.2);transition:height .12s ease,background-color .3s}
.vc.listening .vc-wave i{background:var(--accent)}
.vc-text{min-height:72px;font-size:15px;line-height:1.6;padding:10px 12px;border:1px solid var(--line);background:var(--card-solid)}
.vc-ph{color:var(--muted)}
.vc-ctrl{display:flex;align-items:center;gap:12px;margin-top:14px}
.vc-mic{width:52px;height:52px;flex:none;display:grid;place-items:center;background:var(--accent);color:#120a02;transition:transform .3s var(--ease),background-color .3s}
.vc-mic .ms{font-size:22px}
.vc.listening .vc-mic{background:var(--danger)}
.vc-after{display:flex;gap:8px;margin-left:auto;opacity:0;transform:translateY(4px);pointer-events:none;transition:opacity .3s,transform .4s var(--ease)}
.vc-after.show{opacity:1;transform:none;pointer-events:auto}
.vc-after .btn{padding:8px 14px;font-size:13px}

/* voice capture, compact */
.vc .vc-text{min-height:48px;margin:0 0 12px}
.vc-row{display:flex;align-items:center;gap:10px}
.vc .vc-row .vc-mic{width:38px;height:38px;flex:none}
.vc .vc-row .vc-wave{flex:1;height:30px;margin:0}
.vc .vc-row .vc-after{display:none;gap:6px}
.vc .vc-row .vc-after.show{display:flex}
.vc .vc-row .vc-after.show ~ .x,.vc.done-state #vc-state{display:none}
.vc-row .mono-xs{white-space:nowrap}

/* voice capture: the row never overflows */
.vc .vc-row{min-width:0}
.vc .vc-row .vc-wave{min-width:0;overflow:hidden}
.vc .vc-row .mono-xs{flex:none}
.vc .vc-row:has(.vc-after.show) #vc-state,.vc .vc-row:has(.vc-after.show) .elapsed{display:none}
.vc.listening #vc-state{display:none}

/* ---------- voice capture ---------- */
{
  const vc = $('#vc'), wave = $('#vc-wave'), text = $('#vc-text'), mic = $('#vc-mic'), after = $('#vc-after'), stateEl = $('#vc-state'), timeEl = $('#vc-time');
  const N = 28; wave.innerHTML = '<i></i>'.repeat(N); const bars = $$('i', wave);
  const sentence = 'Make the pricing cards the same height and move the comparison table above the plans.';
  let live = false, raf = 0, ts = [], t0 = 0, phase = 0;
  function flat(){ bars.forEach(b => b.style.height = '4px'); }
  function animate(){
    if (!live) return;
    phase += .18;
    bars.forEach((b, n) => { const env = Math.sin(n / (N - 1) * Math.PI); const v = (Math.sin(phase + n * .7) * .5 + .5) * (.35 + Math.random() * .65); b.style.height = Math.max(3, Math.round(env * v * 26)) + 'px'; });
    const s = Math.floor((performance.now() - t0) / 1000); timeEl.textContent = '0:' + String(s).padStart(2, '0');
    raf = requestAnimationFrame(() => setTimeout(animate, 70));
  }
  function stop(auto){
    if (!live) return; live = false; vc.classList.remove('listening'); cancelAnimationFrame(raf); ts.forEach(clearTimeout); ts = []; flat();
    mic.setAttribute('aria-label', 'Start dictation'); stateEl.textContent = 'Transcribing'; stateEl.classList.add('shimmer'); Sound.play('off');
    setTimeout(() => {
      stateEl.classList.remove('shimmer'); stateEl.textContent = 'Transcript ready';
      text.innerHTML = sentence; text.classList.remove('enter'); void text.offsetWidth; text.classList.add('enter');
      after.classList.add('show'); Sound.play('pop');
    }, 900);
  }
  function start(){
    live = true; vc.classList.add('listening'); after.classList.remove('show'); t0 = performance.now();
    mic.setAttribute('aria-label', 'Stop dictation'); stateEl.textContent = 'Listening'; Sound.play('on');
    text.innerHTML = wordsHTML(sentence); const ws = $$('.w', text);
    ws.forEach((w, n) => ts.push(setTimeout(() => w.classList.add('in'), 500 + n * 260)));
    ts.push(setTimeout(() => stop(true), 500 + ws.length * 260 + 700));
    if (reduce){ bars.forEach((b, n) => b.style.height = Math.round(Math.sin(n / (N - 1) * Math.PI) * 14 + 3) + 'px'); } else animate();
  }
  mic.addEventListener('click', () => live ? stop() : start());
  $('#vc-retry').addEventListener('click', () => { Sound.play('tab'); start(); });
  $('#vc-send').addEventListener('click', () => { Sound.play('send'); showToast('Sent to agent'); after.classList.remove('show'); stateEl.textContent = 'Ready'; timeEl.textContent = '0:00'; text.innerHTML = '<span class="vc-ph">Tap the mic and describe the change you need</span>'; });
  flat();
}
